mapper.select:
SELECT s.id studentId, s.student_no, s.student_name, s.term_id, s.student_identity_id FROM t_as_guardian_student g INNER JOIN t_as_student s ON g.student_identity_id = s.student_identity_id WHERE s.school_id = #{schoolId}
AND s.term_id = #{termId}
AND s.is_valid = 1 AND g.is_valid = 1 AND g.bind_status = 1 AND g.guardian_user_id = #{parentId} ORDER BY s.create_time desc

SELECT distinct b.id FROM t_as_guardian_student a, t_as_student b WHERE a.student_identity_id = b.student_identity_id AND b.register_status = 1 AND a.guardian_user_id = #{parentId} AND a.school_id = #{schoolId}
AND b.term_id = #{termId}
AND b.student_identity_id = #{studentIdentityId}
AND a.bind_status = 1 and a.is_valid = 1 and b.is_valid =1 order by b.grade_id desc,b.id desc
